fn determine_food_safety(x: i8, a: i8, b: i8) -> &'static str {
    // Compute how many days have passed since reference day `a`
    let days_past = b as i16 - a as i16;
    
    // Classify according to the rules:
    // - delicious: days_past <= 0
    // - safe: 0 < days_past <= x
    // - dangerous: days_past > x
    if days_past <= 0 {
        "delicious"
    } else if days_past <= x as i16 {
        "safe"
    } else {
        "dangerous"
    }
}

